import { redirect } from "next/navigation";

/**
 * /{locale}/checkin/[token] — legacy alias of the canonical public check-in
 * route. It performs NO work and writes NO attendance: it simply forwards to
 * the single real implementation at /checkin/[token] (top-level, no locale).
 *
 * WHY THIS EXISTS
 * The QR codes are generated by src/lib/qrcode.ts (`getCheckInUrl`) and always
 * encode the locale-less URL `<siteUrl>/checkin/<token>`, which the i18n
 * middleware deliberately excludes (see src/proxy.ts). That canonical route is
 * read-only: it renders CheckinRunner, which calls the read-only
 * POST /api/checkin (identifyByQrToken) and NEVER records attendance. Recording
 * is staff-only, behind requireStaff on POST /api/attendance/checkin.
 *
 * An earlier version of THIS page was a server component that called
 * checkIn(token) during render — i.e. a GET/prefetch/refresh/link-preview would
 * have recorded attendance — and it also emitted its own <html>/<body> nested
 * inside the [locale] layout. Both are unsafe/incorrect. This redirect removes
 * the write-on-GET and the nested document while still honouring any legacy
 * locale-prefixed check-in links (/ar/checkin/… , /en/checkin/…).
 *
 * The token is forwarded verbatim; if it is not a plausible token the canonical
 * route answers "invalid token" without side effects.
 */
export const dynamic = "force-dynamic";

export default async function LocaleCheckinRedirect({
  params,
}: {
  params: Promise<{ token: string }>;
}) {
  const { token } = await params;
  const safeToken = typeof token === "string" ? token : "";
  redirect(`/checkin/${encodeURIComponent(safeToken)}`);
}

